import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"xclang","text":"Cross-Compiling with Clang","tagline":"Six targets in every archive: Linux, Windows and macOS, each on x64 and arm64. Programs that need nothing but the OS.","actions":[{"theme":"brand","text":"What is xclang?","link":"./guide/what-is-xclang"},{"theme":"alt","text":"Quick Start","link":"./guide/quick-start"},{"theme":"alt","text":"Why xclang?","link":"./guide/why-xclang"}]},"features":[{"title":"Cross-Compiling","details":"A --target flag is all it takes. The sysroots, libc++ and lld for all eight targets come with the toolchain.","link":"./guide/cross-compiling"},{"title":"Self-Contained Programs","details":"A program loads only what its OS has: glibc 2.17 or later, the Windows DLLs, or libSystem. Everything else is linked in.","link":"./design/hermeticity"},{"title":"musl Targets","details":"Fully static Linux programs for x64 and arm64, which need nothing from the system they run on, in every archive.","link":"./reference/targets#musl-targets"},{"title":"Fast Compiles","details":"clang and lld are built with PGO and ThinLTO on every host, Windows included.","link":"./design/pgo#what-it-buys"},{"title":"C++20 Modules","details":"import std in CMake 3.28 or later, without experimental switches, and in Bazel.","link":"./features/modules"},{"title":"Every Build System","details":"CMake, Bazel, Meson, Make and cargo, with xclang from pixi, an archive, FetchContent or the Bazel registry.","link":"./guide/install"},{"title":"Reproducible Builds","details":"Every release is pinned by sha256. Bazel builds carry no absolute paths, so one cache serves every checkout.","link":"./design/bazel-module"},{"title":"MSVC-ABI Targets","details":"Windows x64 and arm64 with Microsoft's CRT and libc++ (or the STL), from every host, with their sanitizers. The xclang command fetches the SDK from Microsoft.","link":"./integrations/clang#msvc-targets"},{"title":"macOS from Any Host","details":"arm64 and x64 macOS programs from Linux and Windows too, with Apple's SDK fetched from Apple by the xclang command.","link":"./guide/cross-compiling#macos-from-linux-or-windows"},{"title":"The xclang Command","details":"Fetches Apple's and Microsoft's SDKs from the vendor, by a pinned version and digest.","link":"./reference/xclang-command"}],"head":[["meta",{"property":"og:title","content":"clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/"}]]},"headers":[],"relativePath":"xclang/index.md","filePath":"en/xclang/index.md","lastUpdated":1791559029000}`),s={name:"xclang/index.md"};function o(r,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n("",4)])])}const p=t(s,[["render",o]]);export{m as __pageData,p as default};
